Multi-Cloud & Hybrid Strategies:
# Multi-cloud Terraform structure
# providers.tf
provider "aws" {
  region = "us-east-1"
  alias  = "aws"
}

provider "azurerm" {
  features {}
  alias = "azure"
}

# main.tf
module "app_aws" {
  source = "./modules/app"
  providers = { aws = aws.aws }
  region = "us-east-1"
}

module "app_azure" {
  source = "./modules/app"
  providers = { azurerm = azurerm.azure }
  region = "eastus"
}

# Disaster recovery: DNS failover
resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.example.com"
  type    = "CNAME"
  ttl     = 60

  set_identifier = "primary"
  records        = [aws_lb.app_aws.dns_name]

  failover_routing_policy {
    type = "PRIMARY"
  }
}

resource "aws_route53_record" "app_dr" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.example.com"
  type    = "CNAME"
  ttl     = 60

  set_identifier = "secondary"
  records        = [azurerm_lb.app_azure.dns_name]

  failover_routing_policy {
    type = "SECONDARY"
  }
}

