# AWS Cost Optimization script
import boto3
from datetime import datetime, timedelta

ce = boto3.client('ce')

def get_cost_recommendations():
    response = ce.get_rightsizing_recommendation(
        Service='AmazonEC2',
        Filter={
            'Dimensions': {
                'Key': 'RECOMMENDATION_TARGET',
                'Values': ['SameInstanceFamily']
            }
        },
        Configuration={
            'RecommendationTarget': 'SAME_INSTANCE_FAMILY',
            'BenefitsConsidered': ['RESERVED_INSTANCE']
        }
    )
    for rec in response['RightsizingRecommendations']:
        print(f"Instance: {rec['AccountId']} - "
              f"Current: {rec['CurrentInstance']['InstanceName']}")
        savings = rec['ModifyRecommendation']
        print(f"  Potential savings: ${savings['EstimatedMonthlySavings']}/mo")

# Spot instance interruption handling
import boto3
ec2 = boto3.client('ec2')

def handle_spot_interruption():
    # Check for spot interruption notice (2 min warning)
    notices = ec2.describe_spot_instance_requests(
        Filters=[{'Name': 'status-code', 'Values': ['marked-for-termination']}]
    )
    for sir in notices['SpotInstanceRequests']:
        instance_id = sir['InstanceId']
        # Drain connections, save state, launch replacement
        print(f"Spot instance {instance_id} marked for termination")
        # Launch on-demand replacement
        ec2.request_spot_instances(
            SpotPrice='0.05',
            InstanceCount=1,
            LaunchSpecification={'InstanceType': 't3.medium'}
        )
